findings.fix:
Create src/app/api/ccz/animais/route.js with GET handler supporting search query parameter:

export async function GET(req) {
  await requireAcessoModulo(MODULOS.CCZ);
  const { searchParams } = new URL(req.url);
  const q = searchParams.get('q');

  const where = {};
  if (q) {
    where.OR = [
      { nome: { contains: q, mode: 'insensitive' } },
      { id: { contains: q, mode: 'insensitive' } }
    ];
  }

  const animais = await prisma.cadastroAnimal.findMany({
    where,
    take: 20,
    orderBy: { nome: 'asc' }
  });
  return NextResponse.json({ success: true, data: animais });
}

